	private static readonly SKPath[] pathTable = new SKPath[0];
	private static readonly SKImage[] imageTable = new SKImage[0];
	private static readonly SKTextBlob[] textBlobTable = new SKTextBlob[0];

	public void Draw(SKCanvas canvas)
	{
		for (var i = 0; i < PartitionCount; i++)
			DrawPartition(canvas, i);
	}

	public void DrawPartition(SKCanvas canvas, int partitionIndex)
	{
		switch (partitionIndex)
		{
			case 0: DrawPartition0(canvas); return;
			case 1: DrawPartition1(canvas); return;
			case 2: DrawPartition2(canvas); return;
			case 3: DrawPartition3(canvas); return;
			case 4: DrawPartition4(canvas); return;
			case 5: DrawPartition5(canvas); return;
			case 6: DrawPartition6(canvas); return;
			case 7: DrawPartition7(canvas); return;
			default: throw new System.ArgumentOutOfRangeException(nameof(partitionIndex));
		}
	}

	// Content prologue — 0 op(s), depth-0 drawing ops that
	// only partition 0 replays (duplicating in other partitions would over-paint
	// them on parallel inserts). Executed once per frame.
	private static void ContentPrologue(SKCanvas canvas)
	{
	}

	// State prologue — 0 op(s), state-only setup that raises
	// the save-stack to baseline depth 0 and establishes matrix/clip.
	// Replayed by every partition, so parallel recorders enter body at identical state.
	private static void StatePrologue(SKCanvas canvas)
	{
	}

	// State epilogue — 0 op(s), closing Restores that unwind
	// the state prologue and return the canvas to depth 0.
	private static void StateEpilogue(SKCanvas canvas)
	{
	}

